function applyPhotoDraft(mode){const E=state.editor,d=E.photoDraft;if(!d||d.needsSetup||!Array.isArray(d.notes)||!d.notes.length){toast('No transcription draft to apply.','warn');return}const p=state.song.parts[state.partIndex];editorCheckpoint();const clean=d.notes.map(n=>({bar:+n.bar||1,beat:+n.beat||1,duration:+n.duration||1,midi:+n.midi||60,velocity:+n.velocity||88,lyric:String(n.lyric||''),rest:!!n.rest}));if(mode==='replace')p.notes=clean;else p.notes=[...(p.notes||[]),...clean].sort((a,b)=>(a.bar-b.bar)||(a.beat-b.beat));if(d.key)state.song.key=d.key;if(d.timeSignature)state.song.timeSignature=d.timeSignature;if(Array.isArray(d.chords)&&d.chords.length)state.song.chords=d.chords;state.song.scoreBars=Math.max(+state.song.scoreBars||8,...clean.map(n=>+n.bar||1));E.selectedIndex=-1;E.photoDraft=null;renderEditor();toast(mode==='replace'?'AI transcription replaced the current part. Review and correct any uncertain notes.':'AI transcription appended. Review and correct any uncertain notes.','ok')}

