function selectedInstruments(){return $$('#instChecks input:checked').map(x=>x.value).slice(0,8)}
function degreeScale(key='C',mode='major'){const roots={C:0,'C#':1,Db:1,D:2,'D#':3,Eb:3,E:4,F:5,'F#':6,Gb:6,G:7,'G#':8,Ab:8,A:9,'A#':10,Bb:10,B:11};const r=roots[key.replace('♭','b').replace('♯','#')]??0,pat=mode==='minor'?[0,2,3,5,7,8,10]:[0,2,4,5,7,9,11];return pat.map(x=>60+r+x)}
function offlineComposition(){const bars=+$('#bars').value||8,style=$('#style').value,idea=$('#idea').value.trim(),key=state.song?.key||state.settings.defaultKey||'C',mode=state.song?.mode||'major',sc=degreeScale(key,mode),prog=[0,4,5,3],chords=[],melody=[];let seed=[...idea+style].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,12345),rnd=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);for(let b=1;b<=bars;b++){const deg=prog[(b-1)%prog.length],root=sc[deg%7];chords.push({bar:b,beat:1,symbol:NOTE.midiName(root,key).replace(/\d+/,'')+(mode==='minor'&&deg===0?'m':'')});let beat=1;for(let k=0;k<4;k++){const dur=rnd()<.22?.5:1,idx=Math.floor(rnd()*5),m=sc[(idx+(b%3))%7]+(rnd()<.3?12:0);melody.push({bar:b,beat,duration:dur,midi:m,lyric:'',velocity:82+Math.floor(rnd()*18)});beat+=dur;if(beat>4.01)break}}return{title:idea?idea.slice(0,44):'Original '+style,key,mode,bpm:style.includes('ballad')?76:style.includes('Dance')?118:92,chords,melody,arrangementNotes:['Original melody generated locally','Edit freely in Music 63 Studio']}}
async function aiCompose(){try{$('#aiCompose').disabled=true;const j=await api('ai_compose',{prompt:$('#idea').value,style:$('#style').value,instruments:selectedInstruments(),bars:+$('#bars').value||8});applyComposition(j.composition)}catch(e){toast(e.message,'danger');$('#aiCompose').disabled=false}}
function applyComposition(comp){const instruments=selectedInstruments();if(!instruments.length){toast('Choose at least one instrument.','warn');return}let s=defaultSong();s.title=comp.title||'New original';s.key=comp.key||'C';s.mode=comp.mode||'major';s.bpm=+comp.bpm||92;s.chords=comp.chords||[];s.notesText=(comp.arrangementNotes||[]).join('\n');s.parts=instruments.map(inst=>{const off=NOTE.INSTRUMENTS[inst]?.soundingOffset||0;return{id:uid('part'),name:NOTE.INSTRUMENTS[inst]?.label||inst,instrument:inst,notes:(comp.melody||[]).map(n=>({...n,midi:Math.max(0,Math.min(127,(+n.midi||60)-off))}))}});state.song=s;state.partIndex=0;toast('Composition created.');show('editor')}
