function renderKeyboard(){const k=$('#kbd');for(let n=21;n<=108;n++){const pc=n%12,black=[1,3,6,8,10].includes(pc),b=document.createElement('button');b.type='button';b.className='key '+(black?'black':'');b.dataset.midi=n;b.textContent=black?'':NOTE.midiName(n).replace(/♯|♭/,'');b.onpointerdown=e=>{e.preventDefault();try{b.setPointerCapture(e.pointerId)}catch(_){}handleMidiEvent({type:'noteon',note:n,velocity:92,channel:1,time:performance.now(),data:[0x90,n,92]})};b.onpointerup=b.onpointercancel=e=>{e.preventDefault();handleMidiEvent({type:'noteoff',note:n,velocity:0,channel:1,time:performance.now(),data:[0x80,n,0]})};k.appendChild(b)}}
function refreshMidiPorts(ports){const m=state.midi;m.ports=ports||{inputs:[],outputs:[]};if(state.view!=='midi')return;const ins=$('#midiInput'),outs=$('#midiOutput');if(ins){ins.innerHTML='<option value="">Choose MIDI input</option>';m.ports.inputs.forEach(i=>{const o=document.createElement('option');o.value=i.id;o.textContent=(i.manufacturer?i.manufacturer+' ':'')+i.name;ins.appendChild(o)});const wanted=m.inputId&&m.ports.inputs.some(x=>x.id===m.inputId)?m.inputId:(m.ports.inputs[0]?.id||'');ins.value=wanted;if(wanted){m.inputId=wanted;MIDI.selectInput(wanted)}ins.onchange=()=>{m.inputId=ins.value;MIDI.selectInput(m.inputId);saveMidiPrefs();setMidiStatus(m.inputId?'MIDI input ready':'No input')}}if(outs){outs.innerHTML='<option value="">No MIDI output</option>';m.ports.outputs.forEach(i=>{const o=document.createElement('option');o.value=i.id;o.textContent=(i.manufacturer?i.manufacturer+' ':'')+i.name;outs.appendChild(o)});const wanted=m.outputId&&m.ports.outputs.some(x=>x.id===m.outputId)?m.outputId:'';outs.value=wanted;if(wanted)MIDI.selectOutput(wanted);outs.onchange=()=>{m.outputId=outs.value;MIDI.selectOutput(m.outputId);saveMidiPrefs()}}setMidiStatus(m.ports.inputs.length?'MIDI ready':'No input found')}
