function renderControllerMap(){const host=$('#controllerMap');if(!host)return;const m=state.midi,targets=[['modulation','Modulation / vibrato'],['volume','Master volume'],['expression','Expression'],['warmth','Warmth'],['brightness','Brightness / tone'],['room','Room / reverb'],['attack','Attack'],['release','Release'],['sustain','Sustain pedal'],['play','Transport: Play'],['stop','Transport: Stop'],['record','Transport: Record']];host.innerHTML='';targets.forEach(([key,label])=>{const cc=Object.entries(m.controlMap).find(([,v])=>v===key)?.[0]??'';const row=document.createElement('div');row.className='controller-row';row.innerHTML=`<span>${h(label)}</span><label>CC <input type="number" min="0" max="127" value="${h(cc)}" placeholder="--"></label><button class="btn small learn ${m.learnTarget===key?'primary':''}">${m.learnTarget===key?'Move control…':'Learn'}</button><button class="btn small clear">Clear</button>`;const input=row.querySelector('input');input.onchange=()=>{Object.keys(m.controlMap).forEach(k=>{if(m.controlMap[k]===key)delete m.controlMap[k]});if(input.value!=='')m.controlMap[String(Math.max(0,Math.min(127,+input.value||0)))]=key;saveMidiPrefs();renderControllerMap()};row.querySelector('.learn').onclick=()=>{m.learnTarget=m.learnTarget===key?'':key;if($('#midiLearnState'))$('#midiLearnState').textContent=m.learnTarget?'Move a knob / slider on the keyboard…':'Ready';renderControllerMap()};row.querySelector('.clear').onclick=()=>{Object.keys(m.controlMap).forEach(k=>{if(m.controlMap[k]===key)delete m.controlMap[k]});if(m.learnTarget===key)m.learnTarget='';saveMidiPrefs();renderControllerMap()};host.appendChild(row)})}
function uiRange(id,value,labelId,text){const e=$('#'+id);if(e)e.value=value;if(labelId&&$('#'+labelId))$('#'+labelId).textContent=text}
