function handleProgramChange(program){const m=state.midi;if(!m.programChange)return;program=+program||0;let inst='Piano';if(program===71)inst='Clarinet Bb';else if(program===65)inst='Alto Sax Eb';else if(program===66)inst='Tenor Sax Bb';else if(program===21)inst='Accordion';else if(program>=24&&program<=31)inst='Guitar';else if(program>=40&&program<=47)inst='Violin';else if(program>=64&&program<=67)inst=program===66?'Tenor Sax Bb':'Alto Sax Eb';m.monitorInstrument=inst;saveMidiPrefs();const sel=$('#monitorInstrument');if(sel)sel.value=inst;setMidiStatus('Loaded '+(NOTE.INSTRUMENTS[inst]?.label||inst)+' from Program '+program);if(m.soundEngine==='studio')AUDIO.prepare(inst).catch(()=>{})}
function handleMidiEvent(e){if(!e||!channelAllowed(e))return;const m=state.midi;if(e.type==='cc'){if($('#meterCc'))$('#meterCc').textContent='CC'+e.controller+' = '+e.value;if(e.controller===1&&$('#meterMod'))$('#meterMod').textContent=e.value;if(e.controller===11&&$('#meterExpression'))$('#meterExpression').textContent=e.value;if(e.controller===64&&$('#meterSustain'))$('#meterSustain').textContent=e.value;if(m.learnTarget){Object.keys(m.controlMap).forEach(k=>{if(m.controlMap[k]===m.learnTarget)delete m.controlMap[k]});m.controlMap[String(e.controller)]=m.learnTarget;const learned=m.learnTarget;m.learnTarget='';saveMidiPrefs();if($('#midiLearnState'))$('#midiLearnState').textContent='Mapped CC'+e.controller+' → '+learned;if(state.view==='midi')renderControllerMap()}const target=m.controlMap[String(e.controller)];if(target)applyMappedControl(target,e.value);if(m.thru&&m.outputId)MIDI.sendEvent(e);return}if(e.type==='program'){handleProgramChange(e.program);if(m.thru&&e.data)MIDI.sendRaw(e.data);return}if(e.type==='aftertouch'){m.modulation=Math.max(0,Math.min(1,(+e.pressure||0)/127));AUDIO.setModulation(m.modulation);if(m.thru&&e.data)MIDI.sendRaw(e.data);return}midiEvent(e);if(e.type==='noteon')editorMidiWriteNote(playedMidi(e.note),velocityValue(e.velocity))}
